#!/usr/bin/env bash
# Adds PIN security + a dedicated User Management page to the fleet
# Admin Panel (the live app — Instances/Kiosk Process/Companies).
#
# NEW:
#   - Users must set a 4-6 digit PIN before they can access anything else
#     (enforced by a global before_request hook) — covers first-ever
#     login (including EXISTING accounts predating this migration, which
#     are gated exactly like a new signup, not silently grandfathered in)
#     and an admin-triggered reset.
#   - PINs expire after a per-company policy (default 90 days / 3 months),
#     admin-configurable to 1/3/6/12 months or a custom number of days.
#     If a user belongs to more than one company, the STRICTEST policy
#     among them applies.
#   - A PIN can never be reused — checked against full history, not just
#     the last N.
#   - A dedicated "Users" page per company (Company home's inline member
#     list/invite form is now a summary + link out to it) with role
#     changes, removal, PIN status at a glance, admin PIN reset, and the
#     PIN expiry policy control — all owner/administrator only.
#
# Files touched: app/models.py, app/__init__.py, app/blueprints/auth.py,
# app/blueprints/companies.py, app/templates/base.html,
# app/templates/auth/pin_setup.html (new),
# app/templates/companies/detail.html, app/templates/companies/users.html
# (new), and a new Alembic migration.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app migrations requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/auth" "backups/$TS/templates/companies"
cp app/models.py "backups/$TS/models.py.bak" 2>/dev/null || true
cp app/__init__.py "backups/$TS/__init__.py.bak" 2>/dev/null || true
cp app/blueprints/auth.py "backups/$TS/auth.py.bak" 2>/dev/null || true
cp app/blueprints/companies.py "backups/$TS/companies.py.bak" 2>/dev/null || true
cp app/templates/base.html "backups/$TS/templates/base.html.bak" 2>/dev/null || true
cp app/templates/companies/detail.html "backups/$TS/templates/companies/detail.html.bak" 2>/dev/null || true
cp -r admin_panel.db "backups/$TS/admin_panel.db.bak" 2>/dev/null || true
echo "==> Backed up existing files (incl. a DB copy - this push includes a migration) to backups/$TS/"

mkdir -p app/templates/auth app/templates/companies

echo "==> Writing app/models.py"
base64 -d > app/models.py << 'MODELS_PY_B64'

MODELS_PY_B64

echo "==> Writing app/__init__.py"
base64 -d > app/__init__.py << 'INIT_PY_B64'

INIT_PY_B64

echo "==> Writing app/blueprints/auth.py"
base64 -d > app/blueprints/auth.py << 'AUTH_PY_B64'

AUTH_PY_B64

echo "==> Writing app/blueprints/companies.py"
base64 -d > app/blueprints/companies.py << 'COMPANIES_PY_B64'

COMPANIES_PY_B64

echo "==> Writing app/templates/base.html"
base64 -d > app/templates/base.html << 'BASE_HTML_B64'

BASE_HTML_B64

echo "==> Writing app/templates/auth/pin_setup.html (new)"
base64 -d > app/templates/auth/pin_setup.html << 'PIN_SETUP_HTML_B64'

PIN_SETUP_HTML_B64

echo "==> Writing app/templates/companies/detail.html"
base64 -d > app/templates/companies/detail.html << 'COMPANY_DETAIL_HTML_B64'

COMPANY_DETAIL_HTML_B64

echo "==> Writing app/templates/companies/users.html (new)"
base64 -d > app/templates/companies/users.html << 'COMPANY_USERS_HTML_B64'

COMPANY_USERS_HTML_B64

echo "==> Writing new Alembic migration (PIN security)"
base64 -d > migrations/versions/3f8b6c1a9d02_add_pin_security.py << 'MIGRATION_PY_B64'

MIGRATION_PY_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/models.py').read())"
python3 -c "import ast; ast.parse(open('app/__init__.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/auth.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/companies.py').read())"
python3 -c "import ast; ast.parse(open('migrations/versions/3f8b6c1a9d02_add_pin_security.py').read())"
echo "    all Python files: syntax OK"

echo ""
echo "==> Applying database migration (PIN fields + user_pin_history table)"
source venv/bin/activate
FLASK_APP=run.py python -m flask db upgrade

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "PIN security + User Management live:"
echo "  - EVERY existing user will be asked to set a PIN on their next"
echo "    request (not just new signups) - this is expected, not a bug."
echo "  - Per-company 'Users' page (owner/administrator only, in the"
echo "    sidebar under each company) - roles, removal, PIN status,"
echo "    admin PIN reset, and the PIN expiry policy control."
echo "  - Default PIN expiry: 90 days (3 months). Change it per company"
echo "    from that Users page."
echo "==================================================================="
